<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\MockObject\MockObject;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\WebAuthnCredential;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;
use Civi\Lughauth\Features\Oidc\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;
use Civi\Lughauth\Features\Oidc\WebAuthn\Application\Usecase\BeginRegistration\BeginRegistrationUsecase;
use Civi\Lughauth\Shared\Exception\NotFoundException;

final class BeginRegistrationUsecaseUnitTest extends TestCase
{
    private TenantReadGateway&MockObject $tenants;
    private UserReadGateway&MockObject $users;
    private WebAuthnChallengeGateway&MockObject $challengeGateway;
    private WebAuthnCredentialGateway&MockObject $credentialGateway;
    private BeginRegistrationUsecase $usecase;

    protected function setUp(): void
    {
        $this->tenants = $this->createMock(TenantReadGateway::class);
        $this->users = $this->createMock(UserReadGateway::class);
        $this->challengeGateway = $this->createMock(WebAuthnChallengeGateway::class);
        $this->credentialGateway = $this->createMock(WebAuthnCredentialGateway::class);

        $this->usecase = new BeginRegistrationUsecase(
            $this->tenants,
            $this->users,
            $this->challengeGateway,
            $this->credentialGateway,
        );
    }

    public function test_returns_options_with_challenge_rp_and_user(): void
    {
        $tenant = $this->buildTenant('tenant-uid', 'acme');
        $user = $this->buildUser('user-uid', 'tenant-uid', 'alice@acme.com', 'Alice');

        $this->tenants->method('findOneByName')->with('acme')->willReturn($tenant);
        $this->users->method('findOneByUid')->with('user-uid')->willReturn($user);
        $this->challengeGateway->expects($this->once())->method('store');
        $this->credentialGateway->method('findByUser')->willReturn([]);

        $options = $this->usecase->begin('user-uid', 'acme', 'acme.example.com', 'Acme Corp');

        $this->assertArrayHasKey('challenge', $options);
        $this->assertArrayHasKey('challengeId', $options);
        $this->assertSame('acme.example.com', $options['rp']['id']);
        $this->assertSame('Acme Corp', $options['rp']['name']);
        $this->assertSame('alice@acme.com', $options['user']['name']);
        $this->assertSame([
            ['alg' => -7, 'type' => 'public-key'],
            ['alg' => -257, 'type' => 'public-key'],
        ], $options['pubKeyCredParams']);
        $this->assertEmpty($options['excludeCredentials']);
    }

    public function test_excludes_existing_credentials(): void
    {
        $tenant = $this->buildTenant('tenant-uid', 'acme');
        $user = $this->buildUser('user-uid', 'tenant-uid', 'alice@acme.com', 'Alice');
        $credential = $this->buildCredential('cred-id-abc');

        $this->tenants->method('findOneByName')->willReturn($tenant);
        $this->users->method('findOneByUid')->willReturn($user);
        $this->challengeGateway->method('store');
        $this->credentialGateway->method('findByUser')->willReturn([$credential]);

        $options = $this->usecase->begin('user-uid', 'acme', 'acme.example.com', 'Acme Corp');

        $this->assertCount(1, $options['excludeCredentials']);
        $this->assertSame('cred-id-abc', $options['excludeCredentials'][0]['id']);
    }

    public function test_challenge_is_stored_in_gateway(): void
    {
        $tenant = $this->buildTenant('tenant-uid', 'acme');
        $user = $this->buildUser('user-uid', 'tenant-uid', 'alice@acme.com', 'Alice');

        $this->tenants->method('findOneByName')->willReturn($tenant);
        $this->users->method('findOneByUid')->willReturn($user);
        $this->credentialGateway->method('findByUser')->willReturn([]);

        $storedChallenge = null;
        $this->challengeGateway->expects($this->once())
            ->method('store')
            ->willReturnCallback(function ($challenge) use (&$storedChallenge) {
                $storedChallenge = $challenge;
            });

        $options = $this->usecase->begin('user-uid', 'acme', 'acme.example.com', 'Acme Corp');

        $this->assertNotNull($storedChallenge);
        $this->assertSame($options['challengeId'], $storedChallenge->challengeId);
        $this->assertSame($options['challenge'], $storedChallenge->challenge);
        $this->assertSame('register', $storedChallenge->type);
        $this->assertSame('user-uid', $storedChallenge->userUid);
    }

    public function test_throws_not_found_when_tenant_missing(): void
    {
        $this->tenants->method('findOneByName')->willReturn(null);
        $this->expectException(NotFoundException::class);

        $this->usecase->begin('user-uid', 'ghost', 'ghost.example.com', 'Ghost');
    }

    public function test_throws_not_found_when_user_missing(): void
    {
        $tenant = $this->buildTenant('tenant-uid', 'acme');
        $this->tenants->method('findOneByName')->willReturn($tenant);
        $this->users->method('findOneByUid')->willReturn(null);

        $this->expectException(NotFoundException::class);
        $this->usecase->begin('no-such-uid', 'acme', 'acme.example.com', 'Acme Corp');
    }

    private function buildTenant(string $uid, string $name): Tenant&MockObject
    {
        $tenant = $this->createMock(Tenant::class);
        $tenant->method('uid')->willReturn($uid);
        $tenant->method('getName')->willReturn($name);
        return $tenant;
    }

    private function buildUser(string $uid, string $tenantUid, string $email, string $name): User&MockObject
    {
        $tenantRef = $this->createMock(\Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef::class);
        $tenantRef->method('uid')->willReturn($tenantUid);

        $user = $this->createMock(User::class);
        $user->method('uid')->willReturn($uid);
        $user->method('getTenant')->willReturn($tenantRef);
        $user->method('getEmail')->willReturn($email);
        $user->method('getName')->willReturn($name);
        return $user;
    }

    private function buildCredential(string $credentialId): WebAuthnCredential
    {
        return new WebAuthnCredential(
            uid: 'uid-1',
            tenantId: 'tenant-uid',
            userUid: 'user-uid',
            username: 'alice@acme.com',
            credentialId: $credentialId,
            publicKey: '-----BEGIN PUBLIC KEY-----',
            signCount: 0,
            aaguid: null,
            deviceName: null,
            transports: null,
            createdAt: new DateTimeImmutable(),
            lastUsedAt: null,
            enabled: true,
        );
    }
}
